import json
from pathlib import Path
q=Path.cwd();a=json.loads((q/'coach-review-actual-labels-export-86a26c44.json').read_bytes());b=json.loads((q/'coach-review-rest-baseline-export-86a26c44.json').read_bytes())
keys=[k for k,v in b.items() if isinstance(v,list)]; changed=[k for k in keys if a[k]!=b[k]];assert len(keys)==36 and sum(len(b[k]) for k in keys)==1084 and set(changed)=={'completedSets','workoutDrafts','workoutDraftLoadUnits'}
