session=added[0]['session_id'];expected=json.loads(a['workoutDrafts'][0]['values_json']);key=added[1]['workout_exercise_id']+':2';expected[key]['duration']='12';assert json.loads(b['workoutDrafts'][0]['values_json'])==expected and b['workoutDrafts'][0]['session_id']==session
stable=lambda rows:[{k:v for k,v in r.items() if k!='updated_at'} for r in rows];assert stable(a['workoutDraftLoadUnits'])==stable(b['workoutDraftLoadUnits']);assert a['workoutSessions']==b['workoutSessions'] and a['trainingCycles']==b['trainingCycles']
r={'appSource':'86a26c44','exportedAt':b['exportedAt'],'receiverOpenedOutsideApp':True,'schemaVersion':17,'arrays':36,'recordsBefore':1082,'recordsAfter':1084,'existingActualsUnchanged':True,'newSavedActuals':[{'set':r['set_number'],'durationSeconds':r['duration_seconds'],'rpe':r['rpe'],'completedAt':r['completed_at']} for r in added],'onlyDraftPayloadEdit':'Selected set2 duration25 to12 plus draft timestamps','sessionAndCycleUnchanged':True,'noNativeSkipClaim':'Both attempts interrupted before Skip; timers expired before continuation'}
